    'tests/lua/battle_ui_slice_4.lua', 'tests/lua/battle_ui_slice_5.lua',
    'tests/lua/battle_ui_slice_6.lua', 'tests/lua/battle_ui_slice_7.lua']
    .some(path => normalizedScript.endsWith(path));
